//! 🧪️ Real export close turns free the quoted allocation, including spare and empty retained capacity.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
#[test]fn close_receipts_quote_physical_buffer_capacity_and_preserve_underfunded_owners(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let snapshot=Arc::new(semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document());let supplier=Arc::clone(&snapshot);let operation=Operation::new(semio_framework_job::OperationId(814),semio_framework_job::RevisionId(37),semio_framework_job::Generation(2),19);let mut job=LayoutExportJob::from_admitted(operation,(operation.operation,operation.generation),LayoutExportRequest{kind:LayoutExportKind::Svg,page_id:None,snapshot,preflight_json:None,parent_document_id:String::new(),canonical_base_revision_hex:String::new()},ArtifactOutputChunks::new(MAX_LAYOUT_EXPORT_OUTPUT_BYTES));let capacity=row["capacity"].as_u64().unwrap()as usize;let length=row["length"].as_u64().unwrap()as usize;let release=row["expectedRelease"].as_u64().unwrap()as usize;let stage=match row["kind"].as_str().unwrap(){"byte"=>{job.png_row=Vec::with_capacity(capacity);job.png_row.resize(length,91);LayoutExportCloseStage::PngRow},"chunk"=>{let mut chunk=Vec::with_capacity(capacity);chunk.resize(length,77);job.output.fixture_transfer(chunk);LayoutExportCloseStage::Output},_=>{job.request.as_mut().unwrap().parent_document_id=String::with_capacity(capacity);LayoutExportCloseStage::ParentAuthority}};let mut caller=layout_export_fixture_caller(operation,operation.generation);job.begin_close();for turn in 0..100000{if job.close_stage==stage{break;}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|job.close_step(cx)).unwrap();assert!(turn<99999);}assert_eq!(job.close_stage,stage);assert_eq!(job.close_demand().unwrap().release_bytes,release);
 let denied=RetainedCloneGrant{maximum_release_bytes:release-1,..LAYOUT_EXPORT_FIXTURE_TURN};let before=match stage{LayoutExportCloseStage::PngRow=>job.png_row.as_ptr()as usize,LayoutExportCloseStage::Output=>job.output.fixture_transfer_ptr(),_=>job.request.as_ref().unwrap().parent_document_id.as_ptr()as usize};let step=caller.turn(denied,|cx|job.close_step(cx)).unwrap();assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(caller.receipt(),Default::default());assert_eq!(job.close_demand().unwrap().release_bytes,release);let after=match stage{LayoutExportCloseStage::PngRow=>job.png_row.as_ptr()as usize,LayoutExportCloseStage::Output=>job.output.fixture_transfer_ptr(),_=>job.request.as_ref().unwrap().parent_document_id.as_ptr()as usize};assert_eq!(before,after);
 let paid=RetainedCloneGrant{maximum_release_bytes:release,..LAYOUT_EXPORT_FIXTURE_TURN};let step=caller.turn(paid,|cx|job.close_step(cx)).unwrap();assert_eq!(step.progress().released_bytes,release);assert_eq!(caller.receipt().released_bytes,release);assert_eq!(match stage{LayoutExportCloseStage::PngRow=>job.png_row.capacity(),LayoutExportCloseStage::Output=>job.output.fixture_transfer_capacity(),_=>job.request.as_ref().unwrap().parent_document_id.capacity()},0);for turn in 0..100000{if job.terminal_is_empty(){break;}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|job.close_step(cx)).unwrap();assert!(turn<99999);}assert!(job.terminal_is_empty());caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK);drop(supplier);
 }
}
